"""决战面板 Mixin — 进入决战总览页。"""

from __future__ import annotations

from autowsgr.infra.logger import get_logger
from autowsgr.types import PageName
from autowsgr.ui.map.base import BaseMapPage
from autowsgr.ui.map.data import CLICK_ENTER_DECISIVE, MapPanel
from autowsgr.ui.substate import SubstateSpec


_log = get_logger('ui')


class DecisivePanelMixin(BaseMapPage):
    """Mixin: 决战面板操作 — 进入决战。"""

    def enter_decisive(self) -> None:
        """从地图页进入决战总览页。

        决战面板由 ``ensure_panel`` 做连续帧复核；进入按钮由
        :class:`~autowsgr.ui.substate.SubstateSpec` 验证到达总览页，
        不再保留两处固定 sleep。

        Raises
        ------
        PageDriftError
            超时未到达决战页面。
        """
        from autowsgr.ui.decisive.battle_page import DecisiveBattlePage

        _log.info('[UI] 地图页面 → 决战页面')

        # 1. 确保在决战面板
        self.ensure_panel(MapPanel.DECISIVE)

        # 2. 点击进入并验证到达决战总览页
        SubstateSpec(
            page=PageName.DECISIVE_BATTLE.value,
            substate='决战总览',
            checker=DecisiveBattlePage.is_current_page,
            timeout=5.0,
            retries=2,
            interval=0.35,
            stable_frames=2,
        ).click(
            self._ctx,
            CLICK_ENTER_DECISIVE,
            source='地图-决战面板',
            action_name='enter_decisive',
        )
